<script setup>import {countryImage} from '../utils/formatters.js';import {ref,onMounted,watch} from 'vue';import {useRoute} from 'vue-router';import {get,message} from '../services/api.js';import RestaurantCard from '../components/restaurants/RestaurantCard.vue';const route=useRoute(),c=ref(null),restaurants=ref([]),error=ref('');async function load(){try{const [a,b]=await Promise.all([get('/countries/'+route.params.slug),get('/countries/'+route.params.slug+'/restaurants')]);c.value=a.data;restaurants.value=b.data;document.title=c.value.name+' Food Guide | BonAppé Find';}catch(e){error.value=message(e);}}watch(()=>route.params.slug,load);onMounted(load);</script>
<template><div class="container section"><p v-if="error" class="error-box" role="alert">{{error}}</p><template v-else-if="c"><nav class="bread" aria-label="Breadcrumb"><RouterLink to="/">Home</RouterLink> / <RouterLink to="/countries">Countries</RouterLink> / {{c.name}}</nav><div class="page-head"><p class="eyebrow muted">{{c.continent}} · Capital {{c.capital}}</p><h1>{{c.name}} Food Guide</h1><p>{{c.tagline}}</p></div><div class="split"><div class="stack"><img :src="countryImage(c.slug)" :alt="'Food and dining inspiration for '+c.name" style="border-radius:20px;width:100%;aspect-ratio:16/9;object-fit:cover"><section class="card pad"><h2>About the food of {{c.name}}</h2><p>{{c.overview}}</p></section><section class="card pad"><h2>What to eat</h2><article v-for="d in c.signatureDishes" :key="d.name"><h3>{{d.name}}</h3><p>{{d.description}}</p></article></section><section class="card pad"><h2>Table manners</h2><ol class="list"><li v-for="tip in c.etiquette" :key="tip">{{tip}}</li></ol></section></div><aside class="stack"><section v-for="[title,text] in [['When people eat',c.mealRhythm],['Tipping and the bill',c.tipping],['Best time to eat',c.bestSeason],['Did you know?',c.funFact]]" :key="title" class="card pad"><h2>{{title}}</h2><p>{{text}}</p></section><section class="card pad"><h2>Say it like a local</h2><h3>{{c.phrase.local}}</h3><p>{{c.phrase.meaning}} · {{c.phrase.language}}</p></section><section class="card pad"><h2>Food festivals</h2><article v-for="f in c.festivals" :key="f.name"><h3>{{f.name}}</h3><p class="small muted">{{f.when}}</p><p>{{f.description}}</p></article></section></aside></div><section class="section"><h2>Restaurants in {{c.name}}</h2><div class="grid"><RestaurantCard v-for="r in restaurants" :key="r._id" :restaurant="r"/></div><p v-if="!restaurants.length">No restaurants from {{c.name}} have been added yet.</p><RouterLink class="btn secondary" :to="{path:'/restaurants',query:{country:c.name}}" style="margin-top:24px">View all {{c.name}} restaurants</RouterLink></section></template><div v-else class="skeleton"></div></div></template>
